+  const owner = readManagedHostRunOwner(paths);
+  if (
+    spec.schemaVersion !== MANAGED_HOST_RUN_SCHEMA_VERSION
+    || spec.runId !== owner.runId
+    || owner.specDigest !== sha256(specText)
